// The engine view's model over records the engine actually publishes
// (req #3760 — coverage map I7 "the record rendered in plain words", and R12's
// read-back half: a stored record renders as it was decided).
//
// `engineViewFixture.json` is generated by scripts/swarm/engine2/view_fixture.py
// from the scenario corpus through `core.decide()`, and
// tests/engine/test_view_fixture.py fails when it goes stale — so every record
// below is a record the engine would publish today.

import { describe, expect, it } from 'vitest';

import fixture from './engineViewFixture.json';
import {
    assembleEngines, engineHealth, enginesForPipeline, historyCells, outcomesByRequirement,
    recordChanges, recordView, scopeKey, scopeText, stoppedAt,
} from '../engineModel';
import { MISSING_AFTER_SECONDS, PLAIN_WORDS } from '../engineVocabulary';

const NOW = new Date(`${fixture.now.replace(' ', 'T')}Z`);
const engines = () => assembleEngines({ states: fixture.engine_states,
    heartbeats: fixture.engine_heartbeats, records: fixture.engine_decision_records, now: NOW });
const byMachine = (m) => engines().find((e) => e.machineId === m);
const rowsOf = (m) => fixture.engine_decision_records.filter((r) => r.machine_fk === m);

describe('engine health — derived from the heartbeat\'s AGE (darwin-mcp engine_health)', () => {
    const at = (s) => new Date(NOW.getTime() - s * 1000).toISOString().replace('T', ' ').slice(0, 19);

    it('a fresh beat is ok, or degraded when it counts failed cycles', () => {
        expect(engineHealth({ desired_state: 'on' }, { beat_at: at(20), health: { degraded_count: 0 } }, NOW))
            .toEqual({ health: 'ok', ageSeconds: 20 });
        expect(engineHealth({ desired_state: 'on' }, { beat_at: at(20), health: { degraded_count: 2 } }, NOW))
            .toEqual({ health: 'degraded', ageSeconds: 20 });
    });

    it('a beat older than the threshold is MISSING while wanted on — with its age, not absent', () => {
        expect(engineHealth({ desired_state: 'on' }, { beat_at: at(MISSING_AFTER_SECONDS), health: {} }, NOW).health)
            .toBe('ok');
        expect(engineHealth({ desired_state: 'on' }, { beat_at: at(MISSING_AFTER_SECONDS + 1), health: {} }, NOW))
            .toEqual({ health: 'missing', ageSeconds: MISSING_AFTER_SECONDS + 1 });
    });

    it('floors the age as the service does: 180.6 s is still fresh', () => {
        const stamp = new Date(NOW.getTime() - 180600).toISOString().replace('T', ' ').slice(0, 23);
        expect(engineHealth({ desired_state: 'on' }, { beat_at: stamp, health: {} }, NOW))
            .toEqual({ health: 'ok', ageSeconds: 180 });
    });

    it('off is stopped, never missing; on with no beat at all is missing with no age', () => {
        expect(engineHealth({ desired_state: 'off' }, { beat_at: at(900), health: {} }, NOW))
            .toEqual({ health: 'stopped', ageSeconds: 900 });
        expect(engineHealth({ desired_state: 'on' }, null, NOW)).toEqual({ health: 'missing', ageSeconds: null });
    });

    it('reads a stamp as UTC, falls back to create_ts, and tolerates a health string', () => {
        expect(engineHealth({ desired_state: 'on' },
            { beat_at: null, create_ts: at(10), health: '{"degraded_count":1}' }, NOW))
            .toEqual({ health: 'degraded', ageSeconds: 10 });
    });
});

describe('assembleEngines — one engine per engine_states row', () => {
    it('joins each state to its beat and to its own scope\'s records, oldest first', () => {
        const all = engines();
        expect(all.map((e) => e.machineId)).toEqual([1, 2, 3, 4]);
        for (const e of all) {
            expect(e.history.map((r) => r.id)).toEqual(rowsOf(e.machineId).map((r) => r.id));
            expect(e.latest.id).toBe(rowsOf(e.machineId).slice(-1)[0].id);
            expect(e.key).toBe(scopeKey(e.pipelineId, e.initiativeId, e.machineId));
        }
    });

    it('reads the fixture\'s four edge cases', () => {
        expect(byMachine(1)).toMatchObject({ health: 'ok', off: false, beatAgeSeconds: 20 });
        expect(byMachine(2)).toMatchObject({ health: 'missing', off: false, beatAgeSeconds: 900 });
        expect(byMachine(3)).toMatchObject({ health: 'stopped', off: true });
        expect(byMachine(4)).toMatchObject({ health: 'degraded', off: false });
    });

    it('an engine turned off stopped when the supervisor said so', () => {
        const e = byMachine(3);
        expect(e.stoppedAt).toBe(e.state.actual_at);
        expect(stoppedAt({ actual_state: 'stopping', desired_at: 'X' }, null)).toBe('X');
        expect(stoppedAt({ actual_state: 'running' }, { beat_at: 'B' })).toBe('B');
    });

    it('scopes to a plan for the plan page\'s Engine mode', () => {
        expect(enginesForPipeline(engines(), 900)).toHaveLength(4);
        expect(enginesForPipeline(engines(), 1)).toHaveLength(0);
    });
});

describe('recordView — a stored record rendered as it was decided (I7, R12)', () => {
    it('keeps every record\'s queue order, codes and cut exactly', () => {
        for (const row of fixture.engine_decision_records) {
            const v = recordView(row.record);
            expect(v.queue.map((q) => [q.epicId, q.requirementId, q.code]))
                .toEqual(row.record.queue.map((i) => [i.epic_id, i.requirement_id, i.code]));
            expect(v.cut).toBe(row.record.cut);
            expect(v.seq).toBe(row.seq);
            expect(v.verdict).toBe(row.verdict);
            expect(v.queue.filter((q) => q.belowCut).length).toBe(row.record.queue.length - row.record.cut);
            for (const q of v.queue) expect(q.words).toBe(PLAIN_WORDS[q.code]);
        }
    });

    it('draws the cut only inside the queue — before the first item no slot was left for', () => {
        // machine 4: dependency-priority, cycle 1 — two admitted, then the cut, then DEP_PRIORITY.
        const v = recordView(rowsOf(4)[0].record);
        expect(v.queue.map((q) => q.code)).toEqual(['ADMITTED', 'ADMITTED', 'DEP_PRIORITY']);
        expect(v.cut).toBe(2);
        expect(v.cutShown).toBe(true);
        expect(v.queue[2].detail).toBe('waiting on epic 101');
        expect(v.epics.find((e) => e.epicId === 102)).toMatchObject({ code: 'DEP_PRIORITY',
            words: PLAIN_WORDS.DEP_PRIORITY });
        // A queue every item of which had a slot: the cut is its length and is not drawn.
        const all = recordView(rowsOf(1)[0].record);
        expect(all.cut).toBe(all.queue.length);
        expect(all.cutShown).toBe(false);
    });

    it('an empty queue is an empty queue, and an ENGINE_HOLD verdict says so', () => {
        const empty = rowsOf(3).find((r) => r.queue_count === 0);
        const v = recordView(empty.record);
        expect(v.queue).toEqual([]);
        expect(v.cutShown).toBe(false);
        expect(v.ok).toBe(false);
        expect(v.verdictDetail).toBeTruthy();
        const unknown = recordView(rowsOf(3).find((r) => r.verdict === 'CAPACITY-UNKNOWN').record);
        expect(unknown.limits).toEqual({ ceiling: null, live: null, reserved: null, free: null });
        expect(unknown.queue[0]).toMatchObject({ code: 'ENGINE_HOLD', detail: 'verdict CAPACITY-UNKNOWN' });
    });

    it('carries the executor\'s answer for each launch THIS record admitted', () => {
        // machine 1: executor-failed-reannounce. Cycle 1 admitted 3001 and the
        // executor failed it; cycle 5 admitted it again and it landed.
        const [first, , , , fifth] = rowsOf(1);
        const v1 = recordView(first.record,
            { outcomes: outcomesByRequirement(fixture.engine_outcomes, first.id) });
        expect(v1.queue[0].outcome).toMatchObject({ state: 'failed', reason: 'iTerm launch refused' });
        const v5 = recordView(fifth.record,
            { outcomes: outcomesByRequirement(fixture.engine_outcomes, fifth.id) });
        expect(v5.queue[0]).toMatchObject({ code: 'ADMITTED', detail: 'announced again (attempt 3)' });
        expect(v5.queue[0].outcome).toMatchObject({ state: 'landed', sessionIds: [3061] });
        // No outcome row yet: an admission reads pending, never blank.
        expect(recordView(first.record).queue[0].outcome.state).toBe('pending');
        // An IN_FLIGHT item carries what the record itself saw.
        expect(recordView(rowsOf(1)[1].record).queue[0].outcome.state).toBe('pending');
    });

    it('returns null for no record', () => {
        expect(recordView(null)).toBe(null);
    });
});

describe('history — what changed and when (A20)', () => {
    it('one cell per stored cycle, oldest first, with what each admitted', () => {
        const cells = historyCells(rowsOf(1).slice().reverse());
        expect(cells.map((c) => c.seq)).toEqual([1, 2, 3, 4, 5, 6, 7]);
        expect(cells.map((c) => c.admitted)).toEqual([1, 0, 1, 0, 1, 0, 0]);
        expect(cells.every((c) => c.ok)).toBe(true);
    });

    it('names each change between two consecutive records', () => {
        const [a, b] = rowsOf(1);
        expect(recordChanges(a.record, b.record)).toContain('requirement 3001: Admitted → In flight');
        expect(recordChanges(a.record, b.record)).toContain('reserved 0 → 1');
        const [h1, h2] = rowsOf(3);
        expect(recordChanges(h1.record, h2.record)).toEqual(expect.arrayContaining([
            'verdict NO-PAUSE-DERIVATION → BUDGET-DERIVED-ONLY', 'requirement 3001 left the queue']));
        expect(recordChanges(null, a.record)).toEqual(['first record in the history shown']);
        expect(recordChanges(a.record, a.record)).toEqual([]);
    });
});

describe('scopeText', () => {
    it('names a whole plan or an initiative of one, with titles when known', () => {
        expect(scopeText(10, null)).toBe('whole plan 10');
        expect(scopeText(10, 7, { pipelineTitle: 'Darwin', initiativeTitle: 'Engine' }))
            .toBe('initiative Engine of plan Darwin');
        expect(scopeText(10, null, { pipelineTitle: 'Darwin' })).toBe('whole plan Darwin');
        expect(scopeText(10, 7)).toBe('initiative 7 of plan 10');
    });
});
